/**
 * Result object for capsule collision
 * @typedef {Object} CapsuleCollisionResult
 * @property {number} penetration - Overlap depth
 * @property {THREE.Vector3} normal - Contact normal (A to B)
 */
/**
 * Test collision between two capsules.
 *
 * A capsule is defined by a line segment (the axis) and a radius.
 * Collision occurs when the distance between the two segments is less
 * than the sum of their radii.
 *
 * @param {Object} bodyA - First body with position, capsuleLength, capsuleRadius
 * @param {Object} bodyB - Second body with position, capsuleLength, capsuleRadius
 * @param {CapsuleCollisionResult} result - Output object (reused to avoid allocations)
 * @returns {boolean} - True if collision detected
 *
 * @example
 * const result = { penetration: 0, normal: new THREE.Vector3() };
 * if ( capsuleCapsuleCollide( bodyA, bodyB, result ) ) {
 *   console.log( 'Collision!', result.penetration );
 * }
 */
export function capsuleCapsuleCollide(bodyA: any, bodyB: any, result: CapsuleCollisionResult): boolean;
/**
 * Result object for capsule collision
 */
export type CapsuleCollisionResult = {
    /**
     * - Overlap depth
     */
    penetration: number;
    /**
     * - Contact normal (A to B)
     */
    normal: THREE.Vector3;
};
